  final bool lastActionWasYank;

  const TuiLineEditor._(
    this.buffer, {
    this.killRing = const [],
    this.killIndex = -1,
    this._undoStack = const [],
    this.lastActionWasYank = false,
  });

  TuiLineEditor([String text = '', int cursor = 0])
    : this._(TuiLineBuffer(text, cursor));

