    next,
    killRing: killRing,
    killIndex: killIndex,
    undoStack: _undoStack,
    lastActionWasYank: lastActionWasYank,
  );

  String get text => buffer.text;
  int get cursor => buffer.cursor;
  bool get canUndo => _undoStack.isNotEmpty;
  bool get canYank => killRing.isNotEmpty;

